1:import type { HarnessMessage } from "./messages.ts";
2:import { approximateTokens } from "./tokens.ts";
3:import { reconstructTurns } from "./turns.ts";
4:
5:/** Turn-size bucket names, smallest first. */
6:export const BUCKETS = ["tiny", "small", "medium", "large", "huge"] as const;
7:
8:/** A Turn's size class by estimated tokens. */
9:export type Bucket = (typeof BUCKETS)[number];
10:
11:/**
12: * Inclusive lower bound of each bucket, ascending in `BUCKETS` order; a
13: * bucket's exclusive upper bound is the next bucket's lower bound, so `huge`
14: * has none.
15: */
16:const FROM: Record<Bucket, number> = {
17:	tiny: 0,
18:	small: 350,
19:	medium: 1800,
20:	large: 7000,
21:	huge: 24000,
22:};
23:
24:/** What a size in each bucket is multiplied by to give its weighted size. */
25:const WEIGHT: Record<Bucket, number> = {
26:	tiny: 0.5,
27:	small: 1,
28:	medium: 1.25,
29:	large: 1.5,
30:	huge: 2.25,
31:};
32:
33:/**
34: * The bucket whose token range holds `tokens`; lower bounds are inclusive.
35: * @throws RangeError if `tokens` is negative or not finite.
36: */
37:export function bucketOf(tokens: number): Bucket {
38:	if (!Number.isFinite(tokens) || tokens < 0) {
39:		throw new RangeError(`Turn size must be a finite, non-negative token count, got ${tokens}`);
40:	}
41:	let bucket: Bucket = BUCKETS[0];
42:	for (const next of BUCKETS) if (tokens >= FROM[next]) bucket = next;
43:	return bucket;
44:}
45:
46:/**
47: * Estimated tokens of each Turn in `messages`, in order: one per Turn that
48: * `reconstructTurns` finds, less a promptless leading one.
49: *
50: * Leading-Turn rule: messages before the first user prompt (a system prompt,
51: * say) are grouped by `reconstructTurns` into a Turn with no prompt. That
52: * Turn answers no user and is dropped, so its messages are not counted. Only
53: * a leading Turn can be promptless; every later Turn starts at a user prompt.
54: * The test is the first message's role, not an empty `prompt`, so a user
55: * prompt with no text still starts a counted Turn.
56: */
57:export function turnSizes(messages: HarnessMessage[]): number[] {
58:	const turns = reconstructTurns(messages);
59:	const promptless = turns[0]?.messages[0]?.role !== "user";
60:	return (promptless ? turns.slice(1) : turns).map((turn) => approximateTokens(turn.messages));
61:}
62:
63:/**
64: * How many of `sizes` fall in each bucket, largest bucket first. Every bucket
65: * has an entry, with count 0 when empty, except `huge`, which is left out
66: * when no size reaches it.
67: * @throws RangeError if a size is negative or not finite, as `bucketOf`.
68: */
69:export function histogram(sizes: number[]): { bucket: Bucket; count: number }[] {
70:	const counts: Record<Bucket, number> = { tiny: 0, small: 0, medium: 0, large: 0, huge: 0 };
71:	for (const size of sizes) counts[bucketOf(size)] += 1;
72:	return BUCKETS.toReversed()
73:		.filter((bucket) => bucket !== "huge" || counts.huge > 0)
74:		.map((bucket) => ({ bucket, count: counts[bucket] }));
75:}
76:
77:/** The plain, unweighted sum of `sizes`; 0 for none. */
78:export function totalOf(sizes: number[]): number {
79:	let total = 0;
80:	for (const size of sizes) total += size;
81:	return total;
82:}
83:
84:/**
85: * Each size times its bucket's weight, parallel to `sizes`. Not rounded.
86: * @throws RangeError if a size is negative or not finite, as `bucketOf`.
87: */
88:export function weighted(sizes: number[]): number[] {
89:	return sizes.map((size) => size * WEIGHT[bucketOf(size)]);
90:}

