1:import type { HarnessMessage } from "./messages.ts";
2:
3:/**
4: * Deterministic stand-in for a tokenizer: the serialized message over four.
5: *
6: * Over the whole message, not its `content` alone: `details`, `toolName` and
7: * `toolCallId` are sent with it and are comparable in size to `content` on a
8: * real tool result. Measured against the harness's own reported figures over
9: * 27 Calls of linear Journals, content-only ran 1.35× low at the median and
10: * whole-message runs 1.15×, which is why the ceiling's default carries the
11: * p90 of that residual as headroom.
12: *
13: * Fields the harness records but does not send onward are excluded, so the
14: * estimate tracks what a provider is billed for rather than what a Journal
15: * happens to keep.
16: */
17:export function approximateTokens(messages: HarnessMessage[]): number {
18:	let characters = 0;
19:	for (const message of messages) characters += serialized(message).length;
20:	return Math.ceil(characters / 4);
21:}
22:
23:/** Recorded by the harness, never sent to the model. */
24:const UNSENT: Record<string, true> = {
25:	contextSnapshot: true,
26:	usage: true,
27:	timestamp: true,
28:	api: true,
29:	provider: true,
30:	model: true,
31:	stopReason: true,
32:};
33:
34:function serialized(message: HarnessMessage): string {
35:	const sent: Record<string, unknown> = {};
36:	// Key order follows the message's own, so the estimate is a function of
37:	// the message and not of insertion history.
38:	for (const [key, value] of Object.entries(message)) {
39:		if (UNSENT[key] === true || value === undefined) continue;
40:		sent[key] = value;
41:	}
42:	return JSON.stringify(sent);
43:}

