10:export function reconstructTurns(messages: HarnessMessage[]): Turn[] {
11:	const turns: Turn[] = [];
12:
13:	for (const message of messages) {
14:		const startsTurn = message.role === "user";
15:		const current = turns[turns.length - 1];
16:
17:		if (startsTurn || current === undefined) {
18:			turns.push({
19:				prompt: startsTurn ? messageText(message) : "",
20:				messages: [message],
21:			});
22:			continue;
23:		}
24:
25:		current.messages.push(message);
26:	}
27:
28:	return turns;
