4:
5:/** Size classes of a Turn by its estimated tokens, smallest first. */
6:export const BUCKETS = ["tiny", "small", "medium", "large", "huge"] as const;
7:
8:export type Bucket = (typeof BUCKETS)[number];
9:
10:/**
11: * Exclusive upper bound of each bucket; its inclusive lower bound is the
12: * previous bucket's upper bound. `huge` is unbounded.
13: */
14:const BELOW: Record<Bucket, number> = {
15:	tiny: 350,
16:	small: 1800,
17:	medium: 7000,
18:	large: 24000,
19:	huge: Number.POSITIVE_INFINITY,
20:};
21:
22:/**
23: * The bucket a Turn of `tokens` estimated tokens falls in.
24: *
25: * @throws {RangeError} when `tokens` is negative, NaN or infinite.
26: */
27:export function bucketOf(tokens: number): Bucket {
28:	if (!Number.isFinite(tokens) || tokens < 0) {
29:		throw new RangeError(`Turn size must be a finite, non-negative token count; got ${tokens}`);
30:	}
31:	return BUCKETS.find((bucket) => tokens < BELOW[bucket]) ?? "huge";
32:}
33:
34:/**
35: * The estimated tokens of each Turn in `messages`, in order, one entry per
36: * Turn that `reconstructTurns` finds.
37: *
38: * Leading-Turn rule: messages before the first user prompt (a system prompt,
39: * say) are grouped by `reconstructTurns` into a leading Turn that has no
40: * prompt. That Turn is dropped, so its messages are not counted and every
41: * returned size belongs to a Turn that opens with a user prompt. A user
42: * prompt with empty text still opens a Turn and is kept.
43: */
44:export function turnSizes(messages: HarnessMessage[]): number[] {
45:	const turns = reconstructTurns(messages);
46:	// Only the first Turn can open with something other than a user prompt.
47:	// Checked by role rather than by an empty `prompt`, which a user prompt
48:	// with no text also has.
49:	if (turns[0]?.messages[0]?.role !== "user") turns.shift();
50:	return turns.map((turn) => approximateTokens(turn.messages));
51:}
52:
53:/**
54: * How many of `sizes` fall in each bucket, largest bucket first. Every bucket
55: * gets an entry, with count 0 when empty, except `huge`, which is left out
56: * when no size falls in it.
57: *
58: * @throws {RangeError} when a size is negative, NaN or infinite.
59: */
60:export function histogram(sizes: number[]): { bucket: Bucket; count: number }[] {
61:	const counts: Record<Bucket, number> = { tiny: 0, small: 0, medium: 0, large: 0, huge: 0 };
62:	for (const size of sizes) counts[bucketOf(size)] += 1;
63:	return [...BUCKETS]
64:		.reverse()
65:		.filter((bucket) => bucket !== "huge" || counts.huge > 0)
66:		.map((bucket) => ({ bucket, count: counts[bucket] }));
67:}
68:
69:/** The plain sum of `sizes`; 0 for an empty list. */
70:export function totalOf(sizes: number[]): number {
71:	return sizes.reduce((total, size) => total + size, 0);
72:}

