91:/**
92: * The sum of the `weighted` sizes of the Turns in each Bucket, keyed like the
93: * `histogram` rows: largest Bucket first, 0 for an empty Bucket, `huge` left
94: * out when no size falls in it. Each size is rounded before summing.
95: *
96: * @throws RangeError when a size is negative, `NaN` or infinite (see `bucketOf`).
97: */
98:export function bucketTotals(sizes: number[]): Map<Bucket, number> {
99:	const totals = new Map<Bucket, number>(histogram(sizes).map(({ bucket }) => [bucket, 0]));
100:	const weights = weighted(sizes);
101:	for (const [index, size] of sizes.entries()) {
102:		const bucket = bucketOf(size);
103:		totals.set(bucket, (totals.get(bucket) ?? 0) + (weights[index] ?? 0));
104:	}
105:	return totals;
106:}
