122:/**
123: * `n` as shown in a rendered table: below 1000 the number as is (`740`);
124: * from 1000 in thousands with one decimal and a `k`, halves rounding up
125: * (1234 is `1.2k`, 1250 is `1.3k`, 12000 is `12.0k`).
126: */
127:export function formatCount(n: number): string {
128:	if (n < 1000) return String(n);
129:	// Rounded in whole hundreds so a half (…50) is exact and rounds up;
130:	// `(n / 1000).toFixed(1)` gives `1.1` for 1150, as 1.15 is stored below 1.15.
