+ */
+export function summaryLine(sizes: number[], budget: number): string {
+	let peak: Bucket | "none" = "none";
+	let over = 0;
+	for (const size of sizes) {
+		const bucket = bucketOf(size);
+		if (peak === "none" || BUCKETS.indexOf(bucket) > BUCKETS.indexOf(peak)) peak = bucket;
+		if (size > OVER) over += 1;
+	}
+	const total = totalOf(sizes);
+	return [
+		`turns=${sizes.length}`,
+		`total=${total}`,
+		`used=${Math.floor((total * 100) / budget)}%`,
+		`peak=${peak}`,
+		`over=${over}`,
+	].join(FIELD_SEPARATOR);
+}
