/** Separates the columns of a rendered row, with no padding (notes/legend.md). */
const SEPARATOR = " | ";

/**
 * The budget table for Turns of `sizes`, one string per row (notes/legend.md):
 * the header, then one row per `histogram` entry in its order, each giving
 * the bucket's label, its Turn count, and its weighted total as `formatCount`
 * shows it.
 *
 * @throws RangeError when a size is negative or not finite, as `bucketOf`.
 */
export function renderTable(sizes: number[]): string[] {
	const totals = bucketTotals(sizes);
	const rows = histogram(sizes).map(({ bucket, count }) =>
		[labelOf(bucket), String(count), formatCount(totals.get(bucket) ?? 0)].join(SEPARATOR),
	);
	return [["bucket", "turns", "weighted"].join(SEPARATOR), ...rows];
}
"})
