import { approximateTokens } from "./tokens.ts";
import { reconstructTurns } from "./turns.ts";

/** Bucket names, smallest first. */
export const BUCKETS = ["tiny", "small", "medium", "large", "huge"] as const;

/** Size class of a Turn by its estimated tokens. */
export type Bucket = (typeof BUCKETS)[number];

/** Exclusive upper bound of each Bucket; `huge` has none. */
const BELOW: Record<Bucket, number> = {
	tiny: 350,
	small: 1800,
	medium: 7000,
	large: 24000,
	huge: Number.POSITIVE_INFINITY,
};

/** What a Turn's size is multiplied by, per Bucket (notes/weights.md). */
const WEIGHT: Record<Bucket, number> = {
	tiny: 0.5,
	small: 1,
	medium: 1.25,
	large: 1.5,
	huge: 2.25,
};

/**
 * The Bucket a Turn of `tokens` estimated tokens falls in; each bound is the
 * next Bucket's start, so 350 is `small` and 24000 is `huge`.
 *
 * @throws RangeError when `tokens` is negative, `NaN` or infinite.
 */
export function bucketOf(tokens: number): Bucket {
	if (!Number.isFinite(tokens) || tokens < 0) {
		throw new RangeError(`Turn size must be a finite, non-negative token count, got ${tokens}`);
	}
	for (const bucket of BUCKETS) if (tokens < BELOW[bucket]) return bucket;
	return "huge";
}

/**
 * Estimated tokens of each Turn in `messages`, in order: one
 * `approximateTokens` estimate per Turn that `reconstructTurns` finds.
 *
 * Leading-Turn rule: messages before the first user prompt (e.g. a system
 * message) come back from `reconstructTurns` as a leading Turn with no prompt.
 * That Turn is dropped, so its tokens count toward no size. It is recognised
 * by its first message not being a user message, not by an empty `prompt`: a
 * real user prompt with empty text still starts a Turn and is kept.
 */
export function turnSizes(messages: HarnessMessage[]): number[] {
	const turns = reconstructTurns(messages);
	const prompted = turns[0]?.messages[0]?.role === "user" ? turns : turns.slice(1);
	return prompted.map((turn) => approximateTokens(turn.messages));
}

/**
 * How many of `sizes` fall in each Bucket, largest Bucket first. Every Bucket
 * gets an entry, count 0 when empty, except `huge`, which is left out when no
 * size falls in it.
 *
 * @throws RangeError when a size is negative, `NaN` or infinite (see `bucketOf`).
 */
export function histogram(sizes: number[]): { bucket: Bucket; count: number }[] {
	const counts: Record<Bucket, number> = { tiny: 0, small: 0, medium: 0, large: 0, huge: 0 };
	for (const size of sizes) counts[bucketOf(size)] += 1;
	return [...BUCKETS]
		.reverse()
		.filter((bucket) => bucket !== "huge" || counts.huge > 0)
		.map((bucket) => ({ bucket, count: counts[bucket] }));
}

/** The plain sum of `sizes`; 0 for an empty list. */
export function totalOf(sizes: number[]): number {
	return sizes.reduce((total, size) => total + size, 0);
}

/**
 * The weighted size of each of `sizes`, in the same order: the size times its
 * Bucket's weight. Not rounded.
 *
 * @throws RangeError when a size is negative, `NaN` or infinite (see `bucketOf`).
 */
export function weighted(sizes: number[]): number[] {
	return sizes.map((size) => size * WEIGHT[bucketOf(size)]);
}
